const fs=require("fs");
const wb=JSON.parse(fs.readFileSync("watchbill.json","utf8"));
const feat=fs.readFileSync("features/todomvc.feature","utf8");
const names=[...feat.matchAll(/^\s*Scenario: (.+)$/gm)].map(m=>m[1].trim());
const contract=[...feat.matchAll(/^\s*@contract\s*\n\s*Scenario: (.+)$/gm)].map(m=>m[1].trim());
const all=new Set(names);
const refs=[];
for(const k of Object.keys(wb).sort()){ if(!/^watch\d+$/.test(k)) {console.log("BAD KEY",k);process.exit(1);} for(const r of wb[k].scenarios) refs.push(r); }
const seen=new Set(); let bad=0;
for(const r of refs){
  const m=r.match(/^(features\/todomvc\.feature):(.+)$/);
  if(!m){console.log("BAD REF FORMAT",r);bad++;continue;}
  const name=m[2].replace(/^:/,"");
  if(!all.has(name)){console.log("MISSING SCENARIO:",name);bad++;}
  if(seen.has(r)){console.log("DUP REF:",r);bad++;} seen.add(r);
}
const refNames=new Set(refs.map(r=>r.split(":").slice(1).join(":").replace(/^features\/todomvc\.feature:/,"")));
for(const n of all){ if(!refNames.has(n)){console.log("ORPHAN SCENARIO (not in watchbill):",n);bad++;} }
console.log("scenarios in feature:",names.length,"| contract:",contract.length,"| watch refs:",refs.length,"| problems:",bad);
process.exit(bad?1:0);
'
